// agentdeck-opencode-plugin v8 — AUTO-GENERATED by AgentDeck.
// Do not edit: reinstalls overwrite this file. Remove it (or set
// AGENTDECK_NO_OPENCODE_HOOKS=1 before installing) to opt out.
//
// Forwards OpenCode lifecycle events to the AgentDeck daemon as
// opencode_* hooks — the same observed-session pipeline Claude Code and
// Codex use — so standalone `opencode` sessions appear on the AgentDeck
// timeline with the same prompt → response turn shape. Every POST is
// nonblocking during a turn, with bounded delivery drained on disposal.
//
// Two plugin APIs, one file: OpenCode 1.x calls the default export's
// `server` (1.4+) or the named export (older); OpenCode 2.x calls
// `setup` with a context whose event stream replaces the 1.x hooks.

import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

const NATIVE_OBSERVER = true;
const nativeReceiverURL = new URL("./agentdeck-connection.json", import.meta.url);
const PORT_TTL_MS = 60000;
let cachedPort = null;
let cachedAt = 0;

// Keep at most one OS read per known registry path in flight. An OS consent
// decision can outlive AbortSignal, so the race also bounds the caller while
// the map prevents retries from exhausting the filesystem worker pool.
const registryReads = new Map();
function readRegistry(path) {
  if (registryReads.has(path)) return registryReads.get(path);
  let timer;
  const io = readFile(path, { encoding: "utf-8", signal: AbortSignal.timeout(200) });
  const bounded = Promise.race([io, new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error("registry read timed out")), 200);
  })]);
  registryReads.set(path, bounded);
  const settled = () => { clearTimeout(timer); registryReads.delete(path); };
  io.then(settled, settled);
  return bounded;
}

async function resolvePort() {
  // The native installation owns an explicit loopback receiver. Re-read on
  // every delivery so a live OpenCode process follows local daemon restarts.
  // Invalid/missing selection never falls through to another daemon.
  if (NATIVE_OBSERVER) {
    try {
      const selection = JSON.parse(await readRegistry(nativeReceiverURL));
      const p = selection.port;
      if (!Number.isInteger(p) || p < 1 || p > 65535) return null;
      const r = await fetch("http://127.0.0.1:" + p + "/health", { signal: AbortSignal.timeout(300) });
      if (!r.ok || (await r.json()).mode !== "daemon") return null;
      return p;
    } catch { return null; }
  }
  const now = Date.now();
  if (cachedPort && now - cachedAt < PORT_TTL_MS) return cachedPort;
  const home = homedir();
  const candidates = [];
  for (const f of [
    join(home, ".agentdeck", "daemon.json"),
    join(home, "Library/Containers/bound.serendipity.agent.deck/Data/Library/Application Support/AgentDeck/daemon.json"),
    join(home, "Library/Group Containers/group.bound.serendipity.agent.deck/daemon.json"),
  ]) {
    try {
      const d = JSON.parse(await readRegistry(f));
      const p = d.httpPort || d.port;
      if (typeof p === "number" && p > 0 && !candidates.includes(p)) candidates.push(p);
    } catch { /* missing/malformed — try next */ }
  }
  if (!candidates.includes(9120)) candidates.push(9120);
  for (const p of candidates) {
    try {
      const r = await fetch("http://127.0.0.1:" + p + "/health", { signal: AbortSignal.timeout(300) });
      if (r.ok) { cachedPort = p; cachedAt = now; return p; }
    } catch { /* dead port — try next */ }
  }
  return null;
}

function deliver(event, body) {
  return resolvePort().then((port) => {
    if (!port) return;
    return fetch("http://127.0.0.1:" + port + "/hooks/" + event, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...body, agentdeck_pid: process.pid, ...(NATIVE_OBSERVER ? { observer_only: true } : {}) }),
      signal: AbortSignal.timeout(800),
    });
  }).catch(() => { /* daemon down — observation is best-effort */ });
}

// ── Steering loop ──
// The daemon queues device commands per session (soft/hard interrupt, prompt
// injection); this loop long-polls GET /opencode/commands and executes them
// through the in-process SDK client — abort is immediate, prompts land even
// while the session is idle. One loop per observed session; stops on
// opencode_stop-less session death via the poll's own error backoff.
const steerLoops = new Set();
// permissionID -> the child session that asked it. A Task-tool child's
// permission is surfaced on its parent's row (a real wait the user must see),
// but OpenCode resolves it against the session that asked.
const permissionSession = new Map();
// Retain only live requests; this is also the authority for command correlation.
const questionRequests = new Map();
let questionRevision = 0;
function permissionTitle(perm) {
  const title = typeof perm.title === "string" ? perm.title : (typeof perm.permission === "string" ? perm.permission : "Permission requested");
  const patterns = Array.isArray(perm.patterns) ? perm.patterns.filter(p => typeof p === "string").join("; ") : "";
  return patterns ? title + ": " + patterns : title;
}

function questionResponderAvailable(client) {
  return typeof client?._client?.post === "function" || typeof client?.question?.reply === "function";
}
function questionPayload(props, sessionID, cwd, client) {
  return {
    session_id: sessionID, question_id: props.id,
    title: (Array.isArray(props.questions) ? props.questions : []).map(q => q.question || q.header || "").filter(Boolean).join(" / "),
    questions: (Array.isArray(props.questions) ? props.questions : []).map(q => ({
      question: q.question, header: q.header, multiple: q.multiple, custom: q.custom,
      options: Array.isArray(q.options) ? q.options.map(o => ({ label: o.label, description: o.description })) : [],
    })),
    question_answerable: questionResponderAvailable(client), cwd,
  };
}
async function replyQuestion(client, sessionID, cmd, post) {
  const pending = questionRequests.get(cmd.questionId);
  if (!pending || pending.session_id !== sessionID || !Array.isArray(cmd.answers)
    || pending.questions.length !== 1 || pending.questions[0].multiple === true
    || cmd.answers.length !== 1 || !Array.isArray(cmd.answers[0]) || cmd.answers[0].length !== 1
    || !pending.questions[0].options.some(o => o.label === cmd.answers[0][0])) return;
  let timer;
  try {
    const signal = AbortSignal.timeout(5000);
    // The v1 plugin client has no question facade in OpenCode 1.18.35.
    // Reuse its existing SDK transport, preserving in-process fetch/auth and
    // directory context; never dial the nominal serverUrl of a standalone TUI.
    const send = typeof client?._client?.post === "function"
      ? client._client.post({ url: "/question/{requestID}/reply", path: { requestID: cmd.questionId },
          query: { directory: pending.cwd }, body: { answers: cmd.answers },
          headers: { "Content-Type": "application/json" }, signal, throwOnError: true })
      : client.question.reply({ requestID: cmd.questionId, answers: cmd.answers, directory: pending.cwd }, { signal, throwOnError: true });
    const result = await Promise.race([send, new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error("question reply timed out")), 5000);
    })]);
    if (result?.error) throw Object.assign(new Error("question reply unconfirmed"), { status: result.response?.status });
  } catch (error) {
    const gone = error?.status === 404 || error?.response?.status === 404;
    if (gone) {
      questionRevision++;
      questionRequests.delete(cmd.questionId);
      post("opencode_question_unavailable", { session_id: pending.session_id, question_id: cmd.questionId, cwd: pending.cwd });
    } else if (questionRequests.has(cmd.questionId)) {
      post("opencode_question_asked", { ...pending, reply_failed: true });
    }
  } finally { clearTimeout(timer); }
}

async function reconcileQuestions(client, sessionID, directory, post) {
  if (typeof client?._client?.get !== "function") return;
  const revision = questionRevision;
  let timer;
  try {
    const read = client._client.get({ url: "/question", query: { directory },
      signal: AbortSignal.timeout(5000), throwOnError: true });
    const result = await Promise.race([read, new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error("question list timed out")), 5000);
    })]);
    // Lifecycle events received during the read outrank its older snapshot.
    if (revision !== questionRevision) return;
    const rows = Array.isArray(result) ? result : result?.data;
    if (!Array.isArray(rows) || !rows.every(q => q && typeof q.id === "string" && typeof q.sessionID === "string")) return;
    const ids = new Set(rows.map(q => q.id));
    for (const [id, pending] of questionRequests) {
      if (pending.session_id === sessionID && !ids.has(id)) {
        questionRequests.delete(id);
        post("opencode_question_unavailable", { session_id: sessionID, question_id: id, cwd: pending.cwd });
      }
    }
    // A readable list can restore a missed initial hook. Keep child routing
    // with the parent's cached identity; a child is not a new top-level row.
    for (const row of rows) {
      const cached = questionRequests.get(row.id);
      if (row.sessionID !== sessionID && cached?.session_id !== sessionID) continue;
      const payload = questionPayload(row, sessionID, cached?.cwd || directory, client);
      questionRequests.set(row.id, payload);
      if (questionRequests.size > 256) questionRequests.delete(questionRequests.keys().next().value);
      post("opencode_question_asked", payload);
    }
  } catch { /* unreadable is not an empty list; retain the known wait */ }
  finally { clearTimeout(timer); }
}

function startSteerLoop(client, sessionID, directory, post) {
  if (NATIVE_OBSERVER || !client || steerLoops.has(sessionID)) return;
  steerLoops.add(sessionID);
  (async () => {
    let failures = 0;
    while (steerLoops.has(sessionID)) {
      const port = await resolvePort();
      if (!port) { await new Promise((r) => setTimeout(r, 30000)); continue; }
      try {
        const r = await fetch(
          "http://127.0.0.1:" + port + "/opencode/commands?sid=" + encodeURIComponent(sessionID) + "&wait=25",
          { signal: AbortSignal.timeout(32000) },
        );
        if (!r.ok) throw new Error("poll " + r.status);
        failures = 0;
        const { commands } = await r.json();
        for (const cmd of commands || []) {
          try {
            if (cmd.type === "interrupt") {
              await client.session.abort({ path: { id: sessionID } });
            } else if (cmd.type === "send_prompt" && cmd.text) {
              const body = { parts: [{ type: "text", text: cmd.text }] };
              // promptAsync (POST /session/{id}/prompt_async) returns
              // immediately; session.prompt BLOCKS until the whole assistant
              // turn completes, so the older fallback must not be awaited or
              // it would stall this loop for the entire turn.
              if (client.session.promptAsync) await client.session.promptAsync({ path: { id: sessionID }, body });
              else if (client.session.prompt) client.session.prompt({ path: { id: sessionID }, body }).catch(() => {});
              else if (client.session.chat) client.session.chat({ path: { id: sessionID }, body }).catch(() => {});
            } else if (cmd.type === "question_reply" && cmd.questionId) {
              await replyQuestion(client, sessionID, cmd, post);
            } else if (cmd.type === "permission_respond" && cmd.permissionId) {
              // Resolve a pending OpenCode permission from the device.
              // "once" (not "always") keeps device-approval one-shot.
              if (client.postSessionIdPermissionsPermissionId) {
                await client.postSessionIdPermissionsPermissionId({
                  path: { id: permissionSession.get(cmd.permissionId) || sessionID, permissionID: cmd.permissionId },
                  body: { response: cmd.response === "allow" ? "once" : "reject" },
                });
              }
            }
          } catch { /* one bad command must not kill the loop */ }
        }
        await reconcileQuestions(client, sessionID, directory, post);
      } catch {
        failures += 1;
        // Backoff on repeated failures so a dead daemon costs one probe/30s.
        await new Promise((r) => setTimeout(r, Math.min(30000, 1000 * failures)));
      }
    }
  })();
}

function stopSteerLoop(sessionID) {
  steerLoops.delete(sessionID);
}

export const AgentDeckObserver = async ({ directory, client }) => {
  // Managed `agentdeck opencode` sessions already stream structured SSE
  // events through their session bridge; posting hooks too would
  // double-count every turn. AGENTDECK_PORT marks a managed PTY.
  if (process.env.AGENTDECK_PORT) return {};
  if (NATIVE_OBSERVER && process.env.AGENTDECK_NO_OPENCODE_HOOKS === "1") return {};

  const cwd = directory;
  const announced = new Set();   // sessionIDs whose opencode_session_start was posted
  const userMsgs = new Map();    // user messageID -> sessionID
  const promptSent = new Set();  // user messageIDs whose prompt_submit was posted
  const promptTimers = new Map();// user messageID -> flush timer
  const responses = new Map();   // sessionID -> latest assistant text
  // sessionID -> { model, provider } of the turn's latest assistant message.
  // Every assistant message.updated carries modelID/providerID, the first one
  // included (10,474 of 10,474 in OpenCode 1.18.35's own event log,
  // 2026-10-18); the stop is the only hook that tells the daemon which model
  // answered, so APME turns from this plugin carried no model at all.
  const models = new Map();
  const startedAt = new Map();   // sessionID -> turn start ms
  const toolPhase = new Map();   // tool callID -> "start" | "end"
  const parentOf = new Map();    // sessionID -> parent sessionID, or null (top level)
  const childStarted = new Set();// child sessionIDs whose opencode_subagent_start was posted
  const childStopped = new Set();// child sessionIDs whose opencode_subagent_stop was posted
  // Background work (OpenCode 1.18 background subagents, measured 2026-10-11):
  // the task tool part completes at once with state.metadata.background and a
  // jobId (the child session id); the end arrives as a synthetic user text
  // <task id="JOB" state="completed"> on the parent.
  const backgroundStarted = new Set(); // jobIds whose opencode_background_start was posted
  const backgroundFinished = new Set();// jobIds whose opencode_background_finish was posted
  const TASK_RESULT = /<task id="([^"]{1,256})" state="([a-z_]{1,40})">/g;

  function noteBackgroundStart(sessionID, part) {
    const meta = part.state && part.state.metadata;
    const job = meta && meta.background === true && typeof meta.jobId === "string" ? meta.jobId : "";
    if (!job || job.length > 256 || backgroundStarted.has(job)) return;
    if (backgroundStarted.size > 512) backgroundStarted.clear();
    backgroundStarted.add(job);
    post("opencode_background_start", { session_id: sessionID, item_id: job, cwd });
  }

  function noteBackgroundResults(sessionID, text) {
    if (text.indexOf("<task id=") < 0) return;
    for (const m of text.matchAll(TASK_RESULT)) {
      if (m[2] === "running" || backgroundFinished.has(m[1])) continue;
      if (backgroundFinished.size > 512) backgroundFinished.clear();
      backgroundFinished.add(m[1]);
      post("opencode_background_finish", { session_id: sessionID, item_id: m[1], status: m[2], cwd });
    }
  }

  function noteSessionInfo(info) {
    if (!info || typeof info.id !== "string" || !info.id) return;
    parentOf.set(info.id, typeof info.parentID === "string" && info.parentID ? info.parentID : null);
    if (parentOf.size > 512) parentOf.delete(parentOf.keys().next().value);
  }

  // A Task-tool child session (OpenCode sets parentID) is its parent's
  // subagent, not a session the user opened: announcing it put a second row
  // on every deck for the length of the task. session.created normally names
  // the parent first; otherwise ask the server once, bounded. An unanswered
  // lookup is unknown and keeps the old behaviour (a row) — it never hides one.
  // OpenCode calls plugin event handlers WITHOUT awaiting them, so every
  // event of an uncached session would race its own lookup and resume out of
  // order (a prompt landing after its own stop opened a phantom turn). One
  // in-flight promise per session makes them all resume in arrival order.
  const parentLookups = new Map(); // sessionID -> Promise<parent|null>
  function lookupParent(sessionID) {
    if (parentOf.has(sessionID)) return Promise.resolve(parentOf.get(sessionID));
    const pending = parentLookups.get(sessionID);
    if (pending) return pending;
    const lookup = (async () => {
      let parent = null;
      try {
        if (client && client.session && client.session.get) {
          const res = await Promise.race([
            client.session.get({ path: { id: sessionID } }),
            new Promise((r) => setTimeout(() => r(null), 1000)),
          ]);
          const info = res && (res.data || res);
          if (info && typeof info.parentID === "string" && info.parentID) parent = info.parentID;
        }
      } catch { /* unknown → top level */ }
      if (!parentOf.has(sessionID)) parentOf.set(sessionID, parent);
      parentLookups.delete(sessionID);
      return parentOf.get(sessionID);
    })();
    parentLookups.set(sessionID, lookup);
    return lookup;
  }

  /** The top-level session a (possibly nested) child belongs to, or null. */
  async function rootSession(sessionID) {
    if (!sessionID) return null;
    let root = null;
    let cur = sessionID;
    for (let hop = 0; hop < 8; hop++) {
      const parent = await lookupParent(cur);
      if (!parent) break;
      root = parent;
      cur = parent;
    }
    return root;
  }

  function eventSessionID(type, props) {
    if (type === "message.updated") return (props.info || {}).sessionID;
    if (type === "message.part.updated") return (props.part || {}).sessionID;
    if (type === "permission.asked" || type === "permission.updated" || type === "permission.replied") {
      const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
      return perm.sessionID;
    }
    return props.sessionID;
  }

  /** Child-session events: lifecycle into the parent's subagent census, a
   *  genuine permission wait onto the parent's row, everything else dropped. */
  function childEvent(type, props, sessionID, parent) {
    // After its stop, a child stays finished: OpenCode re-emits
    // message.updated once a turn settles, and treating that as a new start
    // left the parent's census showing a running child for hours. Only a new
    // user message (the Task tool resuming the child) starts it again.
    if (childStopped.has(sessionID)) {
      const info = props.info || {};
      const resumed = type === "message.updated" && info.role === "user" && info.id && !userMsgs.has(info.id);
      if (!resumed) return;
      childStopped.delete(sessionID);
    }
    if (!childStarted.has(sessionID)) {
      childStarted.add(sessionID);
      if (childStarted.size > 512) childStarted.delete(childStarted.values().next().value);
      const info = props.info || {};
      const label = typeof info.agent === "string" && info.agent ? info.agent
        : (typeof info.mode === "string" && info.mode ? info.mode : "Subagent");
      post("opencode_subagent_start", { session_id: parent, agent_id: sessionID, agent_type: label, cwd });
    }
    if (type === "message.part.updated") {
      const part = props.part || {};
      if (part.type === "text" && typeof part.text === "string" && !userMsgs.has(part.messageID)) {
        responses.set(sessionID, part.text);
      }
    } else if (type === "message.updated") {
      const info = props.info || {};
      if (info.role === "user" && info.id) userMsgs.set(info.id, sessionID);
    } else if (type === "permission.asked" || type === "permission.updated") {
      const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
      if (perm.id) {
        permissionSession.set(perm.id, sessionID);
        if (permissionSession.size > 256) permissionSession.delete(permissionSession.keys().next().value);
        post("opencode_permission_asked", {
          session_id: parent,
          permission_id: perm.id,
          title: permissionTitle(perm),
          cwd,
        });
      }
    } else if (type === "permission.replied") {
      const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
      const id = perm.requestID || perm.permissionID || perm.id || "";
      permissionSession.delete(id);
      post("opencode_permission_replied", { session_id: parent, permission_id: id, cwd });
    } else if (type === "question.asked") {
      // Preserve the child request identity while displaying it on the parent.
      if (props.id) {
        announce(parent);
        const payload = questionPayload(props, parent, cwd, client);
        questionRevision++;
        questionRequests.set(props.id, payload);
        if (questionRequests.size > 256) questionRequests.delete(questionRequests.keys().next().value);
        post("opencode_question_asked", payload);
      }
    } else if (type === "question.replied" || type === "question.rejected") {
      if (props.requestID) {
        questionRevision++;
        questionRequests.delete(props.requestID);
        post(type === "question.replied" ? "opencode_question_replied" : "opencode_question_rejected", {
          session_id: parent, question_id: props.requestID, cwd,
        });
      }
    } else if (type === "session.idle") {
      childStarted.delete(sessionID);
      childStopped.add(sessionID);
      if (childStopped.size > 512) childStopped.delete(childStopped.values().next().value);
      post("opencode_subagent_stop", {
        session_id: parent, agent_id: sessionID,
        last_assistant_message: responses.get(sessionID) || "", cwd,
      });
      responses.delete(sessionID);
    }
  }

  function announce(sessionID) {
    if (!sessionID || announced.has(sessionID)) return;
    announced.add(sessionID);
    post("opencode_session_start", { session_id: sessionID, cwd });
    // Steering: start draining device commands for this session (abort /
    // prompt injection through the in-process client). Loop lives for the
    // opencode process lifetime — sessions in one TUI are few and cheap.
    startSteerLoop(client, sessionID, cwd, post);
  }

  function sendPrompt(messageID, sessionID, prompt) {
    if (promptSent.has(messageID)) return;
    promptSent.add(messageID);
    const t = promptTimers.get(messageID);
    if (t) { clearTimeout(t); promptTimers.delete(messageID); }
    if (!startedAt.has(sessionID)) startedAt.set(sessionID, Date.now());
    post("opencode_user_prompt_submit", { session_id: sessionID, prompt: prompt || "", cwd });
  }

  // OpenCode invokes event hooks without awaiting them, but awaits dispose.
  // A finite run disposes immediately after idle: keep both parent lookups
  // and the subsequent port-read/POST alive until delivery settles. Merely
  // awaiting post inside the event hook does not keep that CLI alive.
  const pendingEvents = new Set();
  const pendingPosts = new Set();
  let closing = false;
  function post(event, body) {
    const pending = deliver(event, body);
    pendingPosts.add(pending);
    pending.then(() => pendingPosts.delete(pending));
    return pending;
  }

  const handleEvent = async ({ event }) => {
      try {
        const type = event.type;
        const props = event.properties || {};
        if (type === "session.created" || type === "session.updated") {
          noteSessionInfo(props.info);
          return;
        }
        const eventSid = eventSessionID(type, props);
        const parent = eventSid ? await rootSession(eventSid) : null;
        if (parent) {
          childEvent(type, props, eventSid, parent);
          return;
        }
        if (type === "message.updated") {
          const info = props.info || {};
          const sessionID = info.sessionID;
          announce(sessionID);
          if (info.role === "user" && info.id) {
            // userMsgs/promptSent are dedup memory keyed on user messageID and
            // must outlive the turn (see the session.idle note), so cap them
            // here instead of clearing per turn — same bound as toolPhase.
            if (userMsgs.size > 512) userMsgs.clear();
            if (promptSent.size > 512) promptSent.clear();
            userMsgs.set(info.id, sessionID);
            // Prompt text usually streams via message.part.updated moments
            // later; flush immediately when the info carries it, otherwise
            // wait briefly so the chat_start row shows the real prompt.
            const direct = typeof info.text === "string" ? info.text
              : (typeof info.content === "string" ? info.content : "");
            if (direct.trim()) {
              sendPrompt(info.id, sessionID, direct.trim());
            } else if (!promptTimers.has(info.id) && !promptSent.has(info.id)) {
              const timer = setTimeout(() => sendPrompt(info.id, sessionID, ""), 800);
              if (typeof timer.unref === "function") timer.unref();
              promptTimers.set(info.id, timer);
            }
          } else if (info.role === "assistant" && typeof info.modelID === "string" && info.modelID.trim()) {
            models.set(sessionID, {
              model: info.modelID.trim().slice(0, 200),
              provider: typeof info.providerID === "string" ? info.providerID.trim().slice(0, 80) : "",
            });
          }
        } else if (type === "message.part.updated") {
          const part = props.part || {};
          const sessionID = part.sessionID;
          announce(sessionID);
          if (part.type === "text" && typeof part.text === "string") {
            noteBackgroundResults(sessionID, part.text);
            const owner = userMsgs.get(part.messageID);
            if (owner) sendPrompt(part.messageID, owner, part.text.trim());
            else responses.set(sessionID, part.text);
          } else if (part.type === "tool" && part.callID) {
            const status = (part.state && part.state.status) || "running";
            if (part.tool === "task") noteBackgroundStart(sessionID, part);
            const phase = toolPhase.get(part.callID);
            if (status === "completed" || status === "error") {
              if (phase !== "end") {
                toolPhase.set(part.callID, "end");
                post("opencode_tool_end", { session_id: sessionID, tool_name: part.tool || "tool", tool_use_id: part.callID, is_error: status === "error", cwd });
              }
            } else if (!phase && status !== "pending") {
              toolPhase.set(part.callID, "start");
              const command = part.state?.input?.command;
              const tool_input = part.tool === "bash" && typeof command === "string" && command.length <= 4096
                ? { command } : undefined;
              post("opencode_tool_start", { session_id: sessionID, tool_name: part.tool || "tool", tool_use_id: part.callID, tool_input, cwd });
            }
            if (toolPhase.size > 512) toolPhase.clear();
          }
        } else if (type === "permission.asked" || type === "permission.updated") {
          // OpenCode emits this only when it is GENUINELY asking the user —
          // no prediction needed, zero false-positive risk. Forward it so
          // devices can render Allow/Deny; the daemon replies through the
          // steering queue as a permission_respond command.
          const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
          const psid = perm.sessionID;
          if (psid && perm.id) {
            announce(psid);
            post("opencode_permission_asked", {
              session_id: psid,
              permission_id: perm.id,
              title: permissionTitle(perm),
              cwd,
            });
          }
        } else if (type === "permission.replied") {
          const perm = (props.permission && typeof props.permission === "object") ? props.permission : (props.info || props);
          const psid = perm.sessionID;
          if (psid) {
            post("opencode_permission_replied", {
              session_id: psid,
              permission_id: perm.requestID || perm.permissionID || perm.id || "",
              cwd,
            });
          }
        } else if (type === "question.asked") {
          if (props.sessionID && props.id) {
            announce(props.sessionID);
            const payload = questionPayload(props, props.sessionID, cwd, client);
            questionRevision++;
            questionRequests.set(props.id, payload);
            if (questionRequests.size > 256) questionRequests.delete(questionRequests.keys().next().value);
            post("opencode_question_asked", payload);
          }
        } else if (type === "question.replied" || type === "question.rejected") {
          if (props.sessionID && props.requestID) {
            questionRevision++;
            questionRequests.delete(props.requestID);
            post(type === "question.replied" ? "opencode_question_replied" : "opencode_question_rejected", {
              session_id: props.sessionID, question_id: props.requestID, cwd,
            });
          }
        } else if (type === "session.idle") {
          const sessionID = props.sessionID;
          announce(sessionID);
          const answered = models.get(sessionID);
          post("opencode_stop", {
            session_id: sessionID,
            last_assistant_message: responses.get(sessionID) || "",
            ...(answered ? { model: answered.model } : {}),
            ...(answered && answered.provider ? { model_provider: answered.provider } : {}),
            cwd,
          });
          responses.delete(sessionID);
          models.delete(sessionID);
          startedAt.delete(sessionID);
          // Do NOT clear userMsgs/promptSent for this session. OpenCode
          // re-emits message.updated for a user message after the turn
          // settles; dropping its promptSent entry let that trailing update
          // re-post opencode_user_prompt_submit, which flips the row back to
          // processing and opens a phantom turn. The session is already idle
          // by then, so no session.idle follows to close it and the row reads
          // WORKING until the 30-min idle TTL evicts it. A messageID is never
          // re-submitted, so these entries are pure dedup memory — bounded
          // where they are added, not here.
        }
      } catch { /* never throw into OpenCode's event loop */ }
  };
  return {
    event(input) {
      if (closing) return Promise.resolve();
      const pending = handleEvent(input);
      pendingEvents.add(pending);
      pending.then(() => pendingEvents.delete(pending));
      return pending;
    },
    async dispose() {
      closing = true;
      for (const timer of promptTimers.values()) clearTimeout(timer);
      promptTimers.clear();
      let deadline;
      try {
        await Promise.race([
          (async () => {
            await Promise.allSettled([...pendingEvents]);
            // An admitted handler can create a prompt timer after the first
            // cancellation above while its parent lookup is still pending.
            for (const timer of promptTimers.values()) clearTimeout(timer);
            promptTimers.clear();
            await Promise.allSettled([...pendingPosts]);
          })(),
          new Promise(resolve => { deadline = setTimeout(resolve, 3000); }),
        ]);
      } finally { clearTimeout(deadline); }
    },
  };
};

// ── OpenCode 2.x ──
// 2.x runs every session in one long-lived server (`opencode serve
// --service`, cwd = the user's home) and calls `setup` once per location
// (directory) it opens. The event stream is process-wide: each location's
// instance receives EVERY location's events, so exactly one instance per
// process forwards them (the first to see an event claims the stream; a
// disposed leader's stream ends and the next event elects another). The
// working directory comes from each session's `location`, never from the
// process cwd — the server's cwd named every session after the home folder.
// Measured on OpenCode 2.4.1 (2026-11-24): session.execution.* bound a turn,
// session.tool.* the tools, permission.asked/replied the approvals,
// form.created/replied/cancelled the question tool, and
// experimental.job.updated the background shells and subagents.
const V2 = globalThis.__agentdeckObserverV2 || (globalThis.__agentdeckObserverV2 = { leader: null, state: null });
const V2_ACTIVE_JOB = new Set(["running", "pending", "queued"]);

function v2State(ctx) {
  if (V2.state) return V2.state;
  V2.state = {
    ctx,
    cwdOf: new Map(),       // sessionID -> directory
    parentOf: new Map(),    // sessionID -> parent sessionID | null
    lookups: new Map(),     // sessionID -> in-flight session.get
    announced: new Set(),
    toolNames: new Map(),   // tool call id -> tool name
    toolStarted: new Set(),
    inbox: new Map(),       // inboxID -> { text, user }
    promptPosted: new Set(),// sessionIDs whose current execution has a prompt
    promptTimers: new Map(),
    responses: new Map(),
    models: new Map(),
    childStarted: new Set(),
    jobs: new Map(),        // active job id -> root sessionID
    permissions: new Map(), // permission id -> the session that asked
    steering: new Set(),
  };
  return V2.state;
}

function cap(store, n) { if (store.size > n) store.delete(store.keys().next().value); }

// Parent and directory of a session the stream did not introduce (it began
// before this server loaded the plugin). Bounded; unanswered is unknown and
// means top level with the directory taken from a later event.
function v2Lookup(s, sessionID) {
  if (!sessionID || (s.parentOf.has(sessionID) && s.cwdOf.has(sessionID))) return Promise.resolve();
  if (s.lookups.has(sessionID)) return s.lookups.get(sessionID);
  let timer;
  const lookup = (async () => {
    try {
      const info = await Promise.race([
        s.ctx.session.get({ sessionID }),
        new Promise((r) => { timer = setTimeout(() => r(null), 1000); }),
      ]);
      const dir = info && info.location && info.location.directory;
      if (typeof dir === "string" && dir && !s.cwdOf.has(sessionID)) s.cwdOf.set(sessionID, dir);
      if (!s.parentOf.has(sessionID)) s.parentOf.set(sessionID, info && typeof info.parentID === "string" && info.parentID ? info.parentID : null);
    } catch { /* unknown → top level */ }
    finally { clearTimeout(timer); }
    cap(s.parentOf, 1024); cap(s.cwdOf, 1024);
    s.lookups.delete(sessionID);
  })();
  s.lookups.set(sessionID, lookup);
  return lookup;
}

/** The top-level session a (possibly nested) subagent belongs to. */
async function v2Root(s, sessionID) {
  let cur = sessionID;
  for (let hop = 0; hop < 8; hop++) {
    await v2Lookup(s, cur);
    const parent = s.parentOf.get(cur);
    if (!parent) return cur;
    cur = parent;
  }
  return cur;
}

function v2Post(s, event, sessionID, body) {
  const cwd = s.cwdOf.get(sessionID);
  return deliver(event, { session_id: sessionID, ...(cwd ? { cwd } : {}), ...body });
}

function v2Announce(s, sessionID) {
  if (s.announced.has(sessionID)) return;
  s.announced.add(sessionID);
  cap(s.announced, 1024);
  v2Post(s, "opencode_session_start", sessionID, {});
  v2SteerLoop(s, sessionID);
}

function v2PromptSubmit(s, sessionID, prompt) {
  const timer = s.promptTimers.get(sessionID);
  if (timer) { clearTimeout(timer); s.promptTimers.delete(sessionID); }
  s.promptPosted.add(sessionID);
  v2Post(s, "opencode_user_prompt_submit", sessionID, { prompt: prompt || "" });
}

function v2PermissionTitle(d) {
  const title = typeof d.action === "string" && d.action ? d.action : "Permission requested";
  const resources = Array.isArray(d.resources) ? d.resources.filter((r) => typeof r === "string").join("; ") : "";
  return resources ? title + ": " + resources : title;
}

// The 2.x plugin context has no form reply, so a question is shown on the
// devices and answered in OpenCode itself (question_answerable: false).
function v2Question(form, sessionID) {
  const fields = Array.isArray(form.fields) ? form.fields : [];
  const questions = fields.map((f) => ({
    question: f.description || f.title || "", header: f.title, multiple: f.type === "array", custom: f.custom,
    options: Array.isArray(f.options) ? f.options.map((o) => ({ label: o.label ?? o.value, description: o.description })) : [],
  }));
  return {
    question_id: form.id,
    title: questions.map((q) => q.question || q.header || "").filter(Boolean).join(" / "),
    questions, question_answerable: false,
  };
}

function v2SteerLoop(s, sessionID) {
  if (NATIVE_OBSERVER || s.steering.has(sessionID)) return;
  s.steering.add(sessionID);
  (async () => {
    let failures = 0;
    while (s.steering.has(sessionID)) {
      const port = await resolvePort();
      if (!port) { await new Promise((r) => setTimeout(r, 30000)); continue; }
      try {
        const r = await fetch("http://127.0.0.1:" + port + "/opencode/commands?sid=" + encodeURIComponent(sessionID) + "&wait=25",
          { signal: AbortSignal.timeout(32000) });
        if (!r.ok) throw new Error("poll " + r.status);
        failures = 0;
        const { commands } = await r.json();
        for (const cmd of commands || []) {
          try {
            if (cmd.type === "interrupt") await s.ctx.session.interrupt({ sessionID });
            else if (cmd.type === "send_prompt" && cmd.text) await s.ctx.session.prompt({ sessionID, text: cmd.text });
            else if (cmd.type === "permission_respond" && cmd.permissionId) {
              // "once" (not "always") keeps device approval one-shot.
              await s.ctx.permission.reply({ sessionID: s.permissions.get(cmd.permissionId) || sessionID,
                requestID: cmd.permissionId, decision: cmd.response === "allow" ? "once" : "reject" });
            }
          } catch { /* one bad command must not kill the loop */ }
        }
      } catch {
        failures += 1;
        await new Promise((r) => setTimeout(r, Math.min(30000, 1000 * failures)));
      }
    }
  })();
}

/** A subagent's events: its run into the parent's census, a genuine wait onto
 *  the parent's row (OpenCode resolves it against the child that asked). */
function v2Child(s, type, d, sid, root) {
  if (type === "session.execution.started") {
    if (s.childStarted.has(sid)) return;
    s.childStarted.add(sid); cap(s.childStarted, 512);
    v2Announce(s, root);
    v2Post(s, "opencode_subagent_start", root, { agent_id: sid, agent_type: "Subagent" });
  } else if (type === "session.text.ended") {
    if (typeof d.text === "string" && d.text.trim()) s.responses.set(sid, d.text);
  } else if (type === "permission.asked") {
    if (!d.id) return;
    s.permissions.set(d.id, sid); cap(s.permissions, 256);
    v2Post(s, "opencode_permission_asked", root, { permission_id: d.id, title: v2PermissionTitle(d) });
  } else if (type === "permission.replied") {
    s.permissions.delete(d.requestID);
    v2Post(s, "opencode_permission_replied", root, { permission_id: d.requestID || "" });
  } else if (type === "form.created") {
    if (d.form && d.form.id) v2Post(s, "opencode_question_asked", root, v2Question(d.form, root));
  } else if (type === "form.replied" || type === "form.cancelled") {
    if (d.id) v2Post(s, type === "form.replied" ? "opencode_question_replied" : "opencode_question_rejected", root, { question_id: d.id });
  } else if (type.startsWith("session.execution.")) {
    if (!s.childStarted.has(sid)) return;
    s.childStarted.delete(sid);
    v2Post(s, "opencode_subagent_stop", root, { agent_id: sid, last_assistant_message: s.responses.get(sid) || "" });
    s.responses.delete(sid);
  }
}

async function v2Handle(s, ev) {
  const type = ev.type;
  const d = ev.data && typeof ev.data === "object" ? ev.data : {};
  const dir = ev.location && typeof ev.location.directory === "string" ? ev.location.directory : "";
  if (type === "session.created") {
    if (!d.sessionID) return;
    s.parentOf.set(d.sessionID, typeof d.parentID === "string" && d.parentID ? d.parentID : null);
    const at = (d.location && d.location.directory) || dir;
    if (at) s.cwdOf.set(d.sessionID, at);
    cap(s.parentOf, 1024); cap(s.cwdOf, 1024);
    return;
  }
  if (type === "experimental.job.updated") {
    // One job id space: background shells (open-ended — a dev server is one)
    // and subagents (they end). A foreground shell reports only its finish,
    // which claims nothing.
    const job = d.info && typeof d.info === "object" ? d.info : {};
    if (typeof job.id !== "string" || !job.id || job.id.length > 256 || typeof job.sessionID !== "string") return;
    const active = V2_ACTIVE_JOB.has(job.status);
    if (active === s.jobs.has(job.id)) return;
    const root = active ? await v2Root(s, job.sessionID) : s.jobs.get(job.id);
    if (active) {
      s.jobs.set(job.id, root); cap(s.jobs, 512);
      v2Announce(s, root);
      v2Post(s, "opencode_background_start", root, { item_id: job.id, item_kind: job.kind === "subagent" ? "job" : "process" });
    } else {
      s.jobs.delete(job.id);
      v2Post(s, "opencode_background_finish", root, { item_id: job.id, status: String(job.status || "") });
    }
    return;
  }
  const sid = typeof d.sessionID === "string" ? d.sessionID : (d.form && typeof d.form.sessionID === "string" ? d.form.sessionID : "");
  if (!sid) return;
  if (dir && !s.cwdOf.has(sid)) s.cwdOf.set(sid, dir);
  const root = await v2Root(s, sid);
  if (root !== sid) return v2Child(s, type, d, sid, root);
  switch (type) {
    case "session.inbox.enqueued": {
      const item = d.item && typeof d.item === "object" ? d.item : {};
      const text = item.payload && typeof item.payload.text === "string" ? item.payload.text : "";
      if (d.inboxID) { s.inbox.set(d.inboxID, { text, user: item.type === "user" }); cap(s.inbox, 256); }
      return;
    }
    case "session.inbox.delivered": {
      const item = s.inbox.get(d.inboxID);
      s.inbox.delete(d.inboxID);
      if (!item) return;
      // A user message opens the turn. A synthetic one (a background result)
      // opens it only when it is what woke the agent.
      if (item.user || (!s.promptPosted.has(sid) && s.promptTimers.has(sid))) {
        v2Announce(s, sid);
        v2PromptSubmit(s, sid, item.text.trim());
      }
      return;
    }
    case "session.execution.started": {
      v2Announce(s, sid);
      // The prompt flag is cleared by the turn's stop, not here: a user
      // message can be delivered just before its execution starts.
      if (!s.promptTimers.has(sid)) {
        const timer = setTimeout(() => { s.promptTimers.delete(sid); if (!s.promptPosted.has(sid)) v2PromptSubmit(s, sid, ""); }, 800);
        if (typeof timer.unref === "function") timer.unref();
        s.promptTimers.set(sid, timer);
      }
      return;
    }
    case "session.step.started":
      if (d.model && typeof d.model.id === "string" && d.model.id.trim()) {
        s.models.set(sid, { model: d.model.id.trim().slice(0, 200), provider: typeof d.model.providerID === "string" ? d.model.providerID.trim().slice(0, 80) : "" });
      }
      return;
    case "session.text.ended":
      if (typeof d.text === "string" && d.text.trim()) s.responses.set(sid, d.text);
      return;
    case "session.tool.input.started":
      if (d.id && d.name) { s.toolNames.set(d.id, d.name); cap(s.toolNames, 512); }
      return;
    case "session.tool.called": {
      if (!d.id || s.toolStarted.has(d.id)) return;
      s.toolStarted.add(d.id); cap(s.toolStarted, 512);
      const name = s.toolNames.get(d.id) || "tool";
      const input = d.input && typeof d.input === "object" ? d.input : {};
      // Same shape the CI-wait classifier reads from Claude's Bash tool.
      const tool_input = name === "shell" && typeof input.command === "string" && input.command.length <= 4096
        ? { command: input.command, run_in_background: input.background === true } : undefined;
      v2Announce(s, sid);
      v2Post(s, "opencode_tool_start", sid, { tool_name: name, tool_use_id: d.id, tool_input });
      return;
    }
    case "session.tool.success":
    case "session.tool.failed":
      if (!d.id || !s.toolStarted.has(d.id)) return;
      s.toolStarted.delete(d.id);
      v2Post(s, "opencode_tool_end", sid, { tool_name: s.toolNames.get(d.id) || "tool", tool_use_id: d.id, is_error: type === "session.tool.failed" });
      s.toolNames.delete(d.id);
      return;
    case "permission.asked":
      if (!d.id) return;
      v2Announce(s, sid);
      s.permissions.set(d.id, sid); cap(s.permissions, 256);
      v2Post(s, "opencode_permission_asked", sid, { permission_id: d.id, title: v2PermissionTitle(d) });
      return;
    case "permission.replied":
      s.permissions.delete(d.requestID);
      v2Post(s, "opencode_permission_replied", sid, { permission_id: d.requestID || "" });
      return;
    case "form.created":
      if (!d.form || !d.form.id) return;
      v2Announce(s, sid);
      v2Post(s, "opencode_question_asked", sid, v2Question(d.form, sid));
      return;
    case "form.replied":
    case "form.cancelled":
      if (d.id) v2Post(s, type === "form.replied" ? "opencode_question_replied" : "opencode_question_rejected", sid, { question_id: d.id });
      return;
    case "session.execution.succeeded":
    case "session.execution.failed":
    case "session.execution.interrupted": {
      if (!s.announced.has(sid)) return;
      if (!s.promptPosted.has(sid)) v2PromptSubmit(s, sid, "");
      const answered = s.models.get(sid);
      v2Post(s, "opencode_stop", sid, {
        last_assistant_message: s.responses.get(sid) || "",
        ...(answered ? { model: answered.model } : {}),
        ...(answered && answered.provider ? { model_provider: answered.provider } : {}),
      });
      s.responses.delete(sid); s.models.delete(sid); s.promptPosted.delete(sid);
      return;
    }
    case "session.deleted":
      if (!s.announced.has(sid)) return;
      v2Post(s, "opencode_session_end", sid, {});
      s.announced.delete(sid); s.steering.delete(sid);
      return;
    default:
      return;
  }
}

async function setupV2(ctx) {
  // Same exclusions as 1.x: a managed PTY's bridge already streams its
  // session, and the macOS app's copy honours the environment opt-out.
  if (process.env.AGENTDECK_PORT) return;
  if (NATIVE_OBSERVER && process.env.AGENTDECK_NO_OPENCODE_HOOKS === "1") return;
  if (!ctx || !ctx.event || typeof ctx.event.subscribe !== "function") return;
  const token = {};
  const s = v2State(ctx);
  (async () => {
    try {
      for await (const ev of ctx.event.subscribe()) {
        if (!V2.leader) { V2.leader = token; s.ctx = ctx; }
        if (V2.leader !== token || !ev || typeof ev.type !== "string") continue;
        try { await v2Handle(s, ev); } catch { /* never throw into OpenCode */ }
      }
    } catch { /* the stream closes with its location */ }
    if (V2.leader === token) V2.leader = null;
  })();
}

export default { id: "agentdeck-observer", server: AgentDeckObserver, setup: setupV2 };
